from fractions import Fraction

def inner(p, q):
    # integral over [-1, 1] of p(x) q(x); p, q are coefficient lists
    total = Fraction(0)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            if (i + j) % 2 == 0:
                total += a * b * Fraction(2, i + j + 1)
    return total

def monic_orthogonal(n):
    # Return [P0, P1, ..., P_{n-1}]; each P_k is monic of degree k
    # and orthogonal to the earlier ones.
    return [[Fraction(0)] * k + [Fraction(1)] for k in range(n)]

